def luhn_valid(s):
    s = filter(str.isdigit, s.replace(" ", ""))  # Eliminer les espaces et s'assurer que c'est une chaîne de chiffres
    if len(s) < 2:
        return False
    def digit_product(n):
        product = 0
        while n > 0:
            n, digit = divmod(n, 10)
            product += digit * (11 - digit)
        return product % 10
    return sum([digit_product(int(d)) for d in s]) % 10 == 0
```

