def parse_duration(s):
    result = None
    for part in s.split('h'):
        if part:
            # Parsing hours
            hours, rest = part.split('m')
            if rest:
                # Parsing minutes
                minutes, s = rest.split('s')
                if minutes and s:
                    # Parsing seconds
                    minutes, s = minutes.split('.')
                    hours, minutes, s = int(hours), int(minutes), int(s or 0)
                    if hours > 0 or minutes > 0:
                        result = hours * 3600 + minutes * 60 + s
    return result
```

