from typing import List

def dedupe_keep_last(items: List[str]) -> List[str]:
    # Début de la solution
    last_occurrence = {}
    deduplicated = []
    for item in items:
        if item not in last_occurrence or last_occurrence[item] == len(items) - 1:
            last_occurrence[item] = len(items)
            deduplicated.append(item)
    # Fin de la solution
    return deduplicated
